L190: /**
L191:  * Handle task subscription (returns async iterator for SSE)
L192:  */
L193: export function subscribeToTask(taskId: string): {
L194:   unsubscribe: () => void;
L195:   events: AsyncGenerator<Task>;
L196: } {
L197:   const task = taskManager.getTask(taskId);
L198:   if (!task) {
L199:     throw { code: ErrorCodes.TASK_NOT_FOUND, message: "Task not found" };
L200:   }
L201: 
L202:   // Capture task for use in generator (TypeScript narrowing doesn't persist into nested functions)
L203:   const initialTask: Task = task;
L204:   let resolve: ((task: Task) => void) | null = null;
L205:   const pending: Task[] = [];
L206: 
L207:   const unsubscribe = taskManager.subscribe(taskId, (updatedTask) => {
L208:     if (resolve) {
L209:       resolve(updatedTask);
L210:       resolve = null;
L211:     } else {
L212:       pending.push(updatedTask);
L213:     }
L214:   });
L215: 
L216:   async function* eventGenerator(): AsyncGenerator<Task> {
L217:     // Yield current state first
L218:     yield initialTask;
L219:     // Then yield updates
L220:     while (true) {
L221:       if (pending.length > 0) {
L222:         yield pending.shift()!;
L223:       } else {
L224:         const update = await new Promise<Task>((r) => {
L225:           resolve = r;
L226:         });
L227:         yield update;
L228: 
L229:         // Stop if terminal state
L230:         const terminalStates = ["COMPLETED", "FAILED", "CANCELLED", "REJECTED"];
L231:         if (terminalStates.includes(update.status.state)) {
L232:           break;
L233:         }
L234:       }
L235:     }
L236:   }
L237:   return {
L238:     unsubscribe,
L239:     events: eventGenerator(),
L240:   };
L241: }

